window.TL = {"duration": 449.57, "scenes": [{"id": "s1", "label": "Opening | Key Conclusion", "start": 0, "end": 31.79}, {"id": "s2", "label": "01 | Market Shifts and the Limitations of Traditional Competition", "start": 31.79, "end": 85.97}, {"id": "s3", "label": "02 | Customer Needs and Pain Points", "start": 85.97, "end": 159.94}, {"id": "s4", "label": "03 | Competitor Perceptions and the Learning Design Gap", "start": 159.94, "end": 236.18}, {"id": "s5", "label": "04 | Repositioning: From workbooks to Learning Design", "start": 236.18, "end": 279.35}, {"id": "s6", "label": "05 | Proposed Positioning Statement and Brand Messages", "start": 279.35, "end": 336.59}, {"id": "s7", "label": "06 | Proposed Strategic Actions", "start": 336.59, "end": 418.23}, {"id": "s8", "label": "Closing", "start": 418.23, "end": 449.57}], "cont": ["s1", "s2", "s3", "s4", "s5", "s6", "s7", "s8"], "order": ["l1_1", "l1_2", "l1_3", "l1_4", "l1_5", "l1_6", "l1_7", "l2_1", "l2_2", "l2_3", "l2_4", "l2_5", "l2_6", "l2_7", "l2_8", "l2_9", "l2_10", "l2_11", "l2_12", "l2_13", "l3_1", "l3_2", "l3_3", "l3_4", "l3_5", "l3_6", "l3_7", "l3_8", "l3_9", "l3_10", "l3_11", "l3_12", "l3_13", "l3_14", "l3_15", "l3_16", "l4_1", "l4_2", "l4_3", "l4_4", "l4_5", "l4_6", "l4_7", "l4_8", "l4_9", "l4_10", "l4_11", "l4_12", "l5_1", "l5_2", "l5_3", "l5_4", "l5_5", "l5_6", "l5_7", "l6_1", "l6_2", "l6_3", "l6_4", "l6_5", "l6_6", "l6_7", "l6_8", "l7_1", "l7_2", "l7_3", "l7_4", "l7_5", "l7_6", "l7_7", "l7_8", "l7_9", "l7_10", "l7_11", "l8_1", "l8_2", "l8_3", "l8_4", "l8_5", "l8_6"], "lines": {"l1_1": {"scene": "s1", "text": "Good morning, everyone.", "start": 0.6, "end": 1.92, "words": [["good", -0.17], ["morning", 0.87], ["everyone", 1.31]]}, "l1_2": {"scene": "s1", "text": "I'm Hyuntae Kim.", "start": 2.37, "end": 3.66, "words": [["i'm", 2.37], ["hyun", 2.63], ["tae", 2.81], ["kim", 2.99]]}, "l1_3": {"scene": "s1", "text": "Today, I will share JEI's core repositioning strategy.", "start": 4.11, "end": 8.16, "words": [["today", 4.11], ["i", 4.77], ["will", 4.81], ["share", 4.97], ["jei's", 5.29], ["core", 6.29], ["repositioning", 6.61], ["strategy", 7.35]]}, "l1_4": {"scene": "s1", "text": "Let me start with our key conclusion.", "start": 8.86, "end": 10.97, "words": [["let", 8.79], ["me", 9.01], ["start", 9.13], ["with", 9.43], ["our", 9.65], ["key", 9.83], ["conclusion", 10.07]]}, "l1_5": {"scene": "s1", "text": "JEI must move beyond competing on workbooks, scale, and digital features.", "start": 11.42, "end": 16.54, "words": [["jei", 11.42], ["must", 12.2], ["move", 12.64], ["beyond", 12.86], ["competing", 13.3], ["on", 13.76], ["workbooks", 13.98], ["scale", 14.68], ["and", 15.28], ["digital", 15.38], ["features", 15.72]]}, "l1_6": {"scene": "s1", "text": "Our goal is to become the brand that designs learning to develop children's ability to learn independently.", "start": 16.99, "end": 22.8, "words": [["our", 16.78], ["goal", 17.22], ["is", 17.46], ["to", 17.64], ["become", 17.76], ["the", 18.04], ["brand", 18.24], ["that", 18.62], ["designs", 18.84], ["learning", 19.3], ["to", 19.68], ["develop", 19.88], ["children's", 20.18], ["ability", 20.74], ["to", 21.1], ["learn", 21.36], ["independently", 21.68]]}, "l1_7": {"scene": "s1", "text": "I will explain the market changes, customer needs, the competitive gap, our positioning, and the strategic actions we need to take.", "start": 23.5, "end": 31.24, "words": [["i", 23.37], ["will", 23.63], ["explain", 23.79], ["the", 24.15], ["market", 24.31], ["changes", 24.61], ["customer", 25.33], ["needs", 25.85], ["the", 26.61], ["competitive", 26.77], ["gap", 27.21], ["our", 27.87], ["positioning", 28.07], ["and", 28.81], ["the", 29.09], ["strategic", 29.21], ["actions", 29.67], ["we", 30.17], ["need", 30.41], ["to", 30.57], ["take", 30.69]]}, "l2_1": {"scene": "s2", "text": "First, let’s look at the challenges we face.", "start": 32.69, "end": 35.18, "words": [["first", 32.57], ["let's", 33.29], ["look", 33.51], ["at", 33.63], ["the", 33.75], ["challenges", 33.85], ["we", 34.25], ["face", 34.53]]}, "l2_2": {"scene": "s2", "text": "Three changes are important.", "start": 35.63, "end": 37.38, "words": [["three", 35.59], ["changes", 35.91], ["are", 36.35], ["important", 36.63]]}, "l2_3": {"scene": "s2", "text": "First, the limitations of our business scale.", "start": 38.08, "end": 40.75, "words": [["first", 38.01], ["the", 38.73], ["limitations", 38.83], ["of", 39.31], ["our", 39.65], ["business", 39.77], ["scale", 40.05]]}, "l2_4": {"scene": "s2", "text": "JEI ranks fourth in the workbook market.", "start": 41.2, "end": 43.81, "words": [["jei", 41.2], ["ranks", 41.9], ["fourth", 42.2], ["in", 42.6], ["the", 42.82], ["workbook", 42.9], ["market", 43.26]]}, "l2_5": {"scene": "s2", "text": "We have about 300 locations, while some competitors have more than 700.", "start": 44.26, "end": 49.1, "words": [["we", 44.26], ["have", 44.42], ["about", 44.6], ["300", 44.82], ["locations", 45.24], ["while", 46.24], ["some", 46.56], ["competitors", 46.82], ["have", 47.34], ["more", 47.72], ["than", 47.96], ["700", 48.1]]}, "l2_6": {"scene": "s2", "text": "It is difficult to compete based on size.", "start": 49.55, "end": 51.95, "words": [["it", 49.45], ["is", 49.71], ["difficult", 49.83], ["to", 50.15], ["compete", 50.37], ["based", 50.73], ["on", 51.03], ["size", 51.23]]}, "l2_7": {"scene": "s2", "text": "Second, changes in the market.", "start": 52.65, "end": 54.61, "words": [["second", 52.6], ["changes", 53.38], ["in", 53.76], ["the", 53.96], ["market", 54.04]]}, "l2_8": {"scene": "s2", "text": "There are fewer children entering school, but spending per child is increasing.", "start": 55.06, "end": 59.6, "words": [["there", 54.93], ["are", 55.19], ["fewer", 55.33], ["children", 55.61], ["entering", 56.03], ["school", 56.43], ["but", 56.91], ["spending", 57.43], ["per", 57.83], ["child", 58.13], ["is", 58.45], ["increasing", 58.77]]}, "l2_9": {"scene": "s2", "text": "This means there are fewer customers, but parents are willing to spend more when they see clear value.", "start": 60.05, "end": 65.57, "words": [["this", 59.81], ["means", 60.29], ["there", 60.55], ["are", 60.75], ["fewer", 60.91], ["customers", 61.23], ["but", 62.11], ["parents", 62.37], ["are", 62.79], ["willing", 62.95], ["to", 63.17], ["spend", 63.35], ["more", 63.65], ["when", 63.99], ["they", 64.23], ["see", 64.37], ["clear", 64.57], ["value", 64.83]]}, "l2_10": {"scene": "s2", "text": "Third, similar features across competitors.", "start": 66.27, "end": 68.99, "words": [["third", 66.26], ["similar", 66.82], ["features", 67.24], ["across", 67.64], ["competitors", 67.96]]}, "l2_11": {"scene": "s2", "text": "AI-based assessment, personalized learning paths, and grading have now become standard features.", "start": 69.44, "end": 75.25, "words": [["ai-based", 69.44], ["assessment", 70.1], ["personalized", 70.92], ["learning", 71.5], ["paths", 71.96], ["and", 72.44], ["grading", 72.84], ["have", 73.18], ["now", 73.44], ["become", 73.62], ["standard", 73.94], ["features", 74.44]]}, "l2_12": {"scene": "s2", "text": "As these features become increasingly common, we need a different basis for competition.", "start": 75.7, "end": 80.89, "words": [["as", 75.54], ["these", 75.98], ["features", 76.2], ["become", 76.58], ["increasingly", 76.9], ["common", 77.48], ["we", 78.26], ["need", 78.64], ["a", 78.8], ["different", 78.92], ["basis", 79.26], ["for", 79.68], ["competition", 79.9]]}, "l2_13": {"scene": "s2", "text": "This is why Learning Design is central to our repositioning strategy.", "start": 81.34, "end": 85.42, "words": [["this", 81.1], ["is", 81.68], ["why", 81.82], ["learning", 82.04], ["design", 82.34], ["is", 82.74], ["central", 83.04], ["to", 83.42], ["our", 83.64], ["repositioning", 83.82], ["strategy", 84.62]]}, "l3_1": {"scene": "s3", "text": "So, what are parents really willing to pay for?", "start": 86.87, "end": 89.53, "words": []}, "l3_2": {"scene": "s3", "text": "We can understand parents’ needs in three layers.", "start": 89.98, "end": 92.8, "words": []}, "l3_3": {"scene": "s3", "text": "The first layer is functional needs: learning materials for different levels, connections to school curricula, and learning data.", "start": 93.5, "end": 101.2, "words": []}, "l3_4": {"scene": "s3", "text": "The second layer is emotional needs.", "start": 101.65, "end": 104.03, "words": []}, "l3_5": {"scene": "s3", "text": "Parents want to worry less about their children falling behind.", "start": 104.48, "end": 107.7, "words": []}, "l3_6": {"scene": "s3", "text": "They also want someone to take care of their children’s learning.", "start": 108.15, "end": 111.11, "words": []}, "l3_7": {"scene": "s3", "text": "The third and most important layer is children’s ability to learn on their own.", "start": 111.81, "end": 116.28, "words": []}, "l3_8": {"scene": "s3", "text": "Why do parents discontinue learning programs?", "start": 116.98, "end": 119.82, "words": []}, "l3_9": {"scene": "s3", "text": "Children may become bored with repetitive activities.", "start": 120.27, "end": 123.29, "words": []}, "l3_10": {"scene": "s3", "text": "Standardized learning pace does not always meet individual needs.", "start": 123.74, "end": 127.7, "words": [["standardized", 123.7], ["learning", 124.52], ["pace", 124.8], ["does", 125.18], ["not", 125.42], ["always", 125.68], ["meet", 126.1], ["individual", 126.4], ["needs", 126.88]]}, "l3_11": {"scene": "s3", "text": "Parents struggle to see clear learning outcomes or understand what their children should learn next.", "start": 128.15, "end": 133.72, "words": [["parents", 127.87], ["struggle", 128.57], ["to", 128.97], ["see", 129.23], ["clear", 129.43], ["learning", 129.85], ["outcomes", 130.15], ["or", 130.69], ["understand", 131.17], ["what", 131.67], ["their", 131.97], ["children", 132.13], ["should", 132.49], ["learn", 132.79], ["next", 133.01]]}, "l3_12": {"scene": "s3", "text": "And much of the responsibility for managing their children's learning still falls on the parents.", "start": 134.17, "end": 139.67, "words": [["and", 134.1], ["much", 134.44], ["of", 134.82], ["the", 134.96], ["responsibility", 135.04], ["for", 135.68], ["managing", 136.1], ["their", 136.48], ["children's", 136.74], ["learning", 137.28], ["still", 137.6], ["falls", 138.28], ["on", 138.72], ["the", 138.9], ["parents", 138.98]]}, "l3_13": {"scene": "s3", "text": "These reasons point to one problem.", "start": 140.37, "end": 142.49, "words": [["these", 140.2], ["reasons", 140.64], ["point", 141.02], ["to", 141.38], ["one", 141.54], ["problem", 141.76]]}, "l3_14": {"scene": "s3", "text": "The problem is not simply a lack of learning materials.", "start": 142.94, "end": 146.06, "words": [["the", 142.71], ["problem", 143.09], ["is", 143.41], ["not", 143.61], ["simply", 143.81], ["a", 144.19], ["lack", 144.39], ["of", 144.65], ["learning", 144.85], ["materials", 145.11]]}, "l3_15": {"scene": "s3", "text": "Parents need a clearer understanding of what their children should learn next, why it matters, and how their learning will progress.", "start": 146.51, "end": 153.46, "words": [["parents", 146.23], ["need", 146.91], ["a", 147.09], ["clearer", 147.21], ["understanding", 147.57], ["of", 148.25], ["what", 148.47], ["their", 148.61], ["children", 148.79], ["should", 149.15], ["learn", 149.49], ["next", 149.73], ["why", 150.47], ["it", 150.69], ["matters", 150.85], ["and", 151.37], ["how", 151.69], ["their", 151.93], ["learning", 152.15], ["will", 152.45], ["progress", 152.69]]}, "l3_16": {"scene": "s3", "text": "This is why we must shift our focus from workbooks to how children’s ability to learn improves.", "start": 153.91, "end": 159.39, "words": []}, "l4_1": {"scene": "s4", "text": "Now, let’s look at whether our competitors are meeting this need.", "start": 160.84, "end": 164.63, "words": []}, "l4_2": {"scene": "s4", "text": "These evaluations are based on customer perceptions.", "start": 165.08, "end": 168.25, "words": []}, "l4_3": {"scene": "s4", "text": "Each of our three major competitors is associated with a different strength.", "start": 168.95, "end": 173.12, "words": []}, "l4_4": {"scene": "s4", "text": "Daekyo emphasizes level-based learning, Kumon is known for repetition and building study habits, and Woongjin focuses on online and AI-powered learning platforms.", "start": 173.57, "end": 183.96, "words": []}, "l4_5": {"scene": "s4", "text": "Daekyo does not have a clear long-term learning plan.", "start": 184.66, "end": 187.77, "words": []}, "l4_6": {"scene": "s4", "text": "Kumon can become boring, causing children to lose interest.", "start": 188.22, "end": 191.94, "words": []}, "l4_7": {"scene": "s4", "text": "Woongjin's platform may feel complex, while screen-based learning can raise concerns about insufficient handwriting practice.", "start": 192.39, "end": 199.53, "words": []}, "l4_8": {"scene": "s4", "text": "Above all, no company clearly answers the question parents really ask: “Where should my child’s learning be in three years?”", "start": 200.23, "end": 207.83, "words": []}, "l4_9": {"scene": "s4", "text": "This is where “Design” comes in.", "start": 208.28, "end": 210.05, "words": []}, "l4_10": {"scene": "s4", "text": "It means setting a direction after diagnosis and helping children stay motivated along the way.", "start": 210.5, "end": 216.06, "words": []}, "l4_11": {"scene": "s4", "text": "According to Al Ries’s positioning principles, it is very difficult for a company ranked fourth to beat the leader in the same category.", "start": 216.76, "end": 224.4, "words": []}, "l4_12": {"scene": "s4", "text": "Rather than trying to move up the existing competitive ladder, JEI aims to establish a new ladder centered on Learning Design—one where we can build a distinctive leadership position.", "start": 224.85, "end": 235.63, "words": []}, "l5_1": {"scene": "s5", "text": "We will move from selling workbooks to providing Learning Design.", "start": 237.08, "end": 240.76, "words": []}, "l5_2": {"scene": "s5", "text": "We aim to provide personalized learning roadmaps that help each child understand what to learn next and how to progress.", "start": 241.21, "end": 248.32, "words": []}, "l5_3": {"scene": "s5", "text": "We will build on our existing strengths: the JEI Self-Learning Method, diagnostic assessment, and structured learning materials.", "start": 249.02, "end": 256.98, "words": []}, "l5_4": {"scene": "s5", "text": "But we will define self-learning as an ability, not just the act of studying.", "start": 257.43, "end": 261.94, "words": []}, "l5_5": {"scene": "s5", "text": "This builds on the nearly 50-year legacy of the JEI Self-Learning Method.", "start": 262.39, "end": 266.94, "words": []}, "l5_6": {"scene": "s5", "text": "Our focus is not simply to have more locations or members than competitors.", "start": 267.64, "end": 272.01, "words": []}, "l5_7": {"scene": "s5", "text": "We want to create clear learning paths for individual students and become a leader in the Learning Design category.", "start": 272.46, "end": 278.8, "words": []}, "l6_1": {"scene": "s6", "text": "Our proposed positioning statement is: \"JEI designs learning to develop children's ability to learn independently.\"", "start": 280.25, "end": 287.26, "words": []}, "l6_2": {"scene": "s6", "text": "This statement reflects our shift from simply providing workbooks to developing children's Self-Learning Ability through Learning Design.", "start": 287.96, "end": 295.57, "words": []}, "l6_3": {"scene": "s6", "text": "Our brand messaging is built around two key concepts: \"Design\" and \"Self-Learning Ability.\"", "start": 296.27, "end": 301.73, "words": []}, "l6_4": {"scene": "s6", "text": "We have proposed several slogan options, including \"Learning starts with design,\" \"Studying starts with design,\" and \"Beyond Workbooks. Toward Learning Design.\"", "start": 302.43, "end": 311.67, "words": []}, "l6_5": {"scene": "s6", "text": "Our proposed campaign message is: \"It's not a lack of ability. It's a lack of learning design.\"", "start": 312.37, "end": 317.89, "words": []}, "l6_6": {"scene": "s6", "text": "And our customer value message is: \"The ability to learn independently begins with Learning Design.\"", "start": 318.59, "end": 324.38, "words": []}, "l6_7": {"scene": "s6", "text": "These are proposed expressions, not finalized brand slogans.", "start": 325.08, "end": 329.01, "words": []}, "l6_8": {"scene": "s6", "text": "Whatever we ultimately choose, our messages must reinforce a clear and consistent position in customers' minds.", "start": 329.46, "end": 336.04, "words": []}, "l7_1": {"scene": "s7", "text": "Finally, let me outline five strategic priorities for execution.", "start": 337.49, "end": 341.6, "words": []}, "l7_2": {"scene": "s7", "text": "First, we will focus on our strongest core subjects rather than promoting all 17 subjects equally.", "start": 342.3, "end": 348.57, "words": []}, "l7_3": {"scene": "s7", "text": "This will allow us to build a clear and differentiated Learning Design approach.", "start": 349.02, "end": 353.68, "words": []}, "l7_4": {"scene": "s7", "text": "Second, we will strengthen the connection between assessment, Learning Design, and coaching.", "start": 354.38, "end": 359.51, "words": []}, "l7_5": {"scene": "s7", "text": "Each child's learning needs will be assessed, the next learning steps will be designed, and instructors will provide personalized guidance along the way.", "start": 359.96, "end": 368.26, "words": []}, "l7_6": {"scene": "s7", "text": "Third, we will continue to emphasize the role of our instructors.", "start": 368.96, "end": 372.75, "words": []}, "l7_7": {"scene": "s7", "text": "While AI-powered learning solutions are important, personal guidance and ongoing learning support remain key reasons why parents choose JEI.", "start": 373.2, "end": 382.01, "words": []}, "l7_8": {"scene": "s7", "text": "Fourth, we will communicate a consistent brand message across our products, learning centers, local offices, and advertising.", "start": 382.71, "end": 390.2, "words": []}, "l7_9": {"scene": "s7", "text": "\"Design\" and \"Self-Learning Ability\" should remain central to how we present our brand.", "start": 390.65, "end": 395.68, "words": []}, "l7_10": {"scene": "s7", "text": "Fifth, we will focus on increasing value per customer and recognize the importance of multi-subject learning, while avoiding competition based solely on the number of subjects or overall business scale.", "start": 396.38, "end": 408.57, "words": []}, "l7_11": {"scene": "s7", "text": "Together, these priorities will help JEI strengthen its position in Learning Design and deliver greater value to children and their families.", "start": 409.27, "end": 417.68, "words": []}, "l8_1": {"scene": "s8", "text": "To summarize, JEI aims to move beyond workbooks and establish a leadership position in Learning Design by designing learning to develop children's ability to learn independently.", "start": 419.13, "end": 429.83, "words": []}, "l8_2": {"scene": "s8", "text": "To achieve this, we must change first.", "start": 430.53, "end": 432.85, "words": []}, "l8_3": {"scene": "s8", "text": "When we develop products, meet customers, and discuss ideas in meetings, we must all use the same language.", "start": 433.3, "end": 439.44, "words": []}, "l8_4": {"scene": "s8", "text": "Starting today, our shared message is “Designing the Ability to Learn.”", "start": 439.89, "end": 444.18, "words": []}, "l8_5": {"scene": "s8", "text": "Thank you.", "start": 444.88, "end": 445.55, "words": []}, "l8_6": {"scene": "s8", "text": "Please feel free to ask any questions.", "start": 446.0, "end": 448.37, "words": []}}};
